"""Assemble one View module: the Host loads Project Views through blob URLs."""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
helpers = (root / "src/views/ng-document.js").read_text()
entry = (root / "src/views/view-ng.js").read_text()
compiler = (root / "src/lua/compile-graph.lua").read_text()
output = root / "build.nosync/views/view-ng.js"
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(
    "// Generated by Make; edit src/, not this file.\n"
    + "const NG_COMPILER_SOURCE = " + json.dumps(compiler) + ";\n"
    + helpers.replace("export function ", "function ")
    + "\n" + entry
)
